+static void
+read_unprimed_hfinfo(header_field_info *hfinfo, proto_tree *tree, GHashTable *fv_set)
+{
+	GPtrArray *finfos;
+	field_info *finfo;
+
+	while (hfinfo) {
+		finfos = proto_find_finfo(tree, hfinfo->id);
+		if (finfos == NULL) {
+			hfinfo = hfinfo->same_name_next;
+			continue;
+		}
+
+		for (guint i = 0; i < finfos->len; i++) {
+			finfo = g_ptr_array_index(finfos, i);
+
+			/* Insert the fvalues for the filter_name:hfinfo key into the set with deduplication. */
+			/* Old key is freed if duplicate. */
+			g_hash_table_add(fv_set, fvalue_dup(finfo->value));
+		}
+
+		g_ptr_array_free(finfos, TRUE);
+		hfinfo = hfinfo->same_name_next;
+	}
+}
+
+static void
+load_recursive_references(dfilter_t *df, proto_tree *tree, const char *filter_name)
+{
+	/* Fetch the set of hfinfos, read them from the tree and store them in recursive references map. */
+
+	WS_DEBUG_HERE("matched");
+
+	df_hfset_t *hf_set = df_hfmap_lookup(df->recursive_hfmap, filter_name);
+	if (hf_set == NULL) {
+		return;
+	}
+	GHashTableIter iter;
+	header_field_info *hfinfo;
+
+	g_hash_table_iter_init(&iter, hf_set);
+	while (g_hash_table_iter_next(&iter, (void **)&hfinfo, NULL)) {
+		dfvm_recursive_key_t key;
+
+		key.filter_name = (char *)filter_name;
+		key.hfinfo = hfinfo;
+
+		GHashTable *fv_set = g_hash_table_lookup(df->recursive_references, &key);
+		/* Set was already created. */
+		ws_assert(fv_set);
+
+		read_unprimed_hfinfo(hfinfo, tree, fv_set);
+	}
+}
+
+/* Load references for each filter_name:field.*/
+void
+dfilter_load_recursive_references(dfilter_t *dfcode, proto_tree *tree)
+{
+	GHashTableIter iter;
+	const char *filter_name;
+	dfilter_t *filter;
+
+	/* First we need to check it the tree matches each filter individually. */
+	g_hash_table_iter_init(&iter, dfcode->recursive_filter_sets);
+	while (g_hash_table_iter_next(&iter, (void **)&filter_name, (void **)&filter)) {
+		if (dfilter_apply(filter, tree)) {
+			/* It's a match */
+			load_recursive_references(dfcode, tree, filter_name);
+		}
+	}
+}
+
+void
+dfilter_reset_recursion(dfilter_t *dfcode)
+{
+	g_hash_table_remove_all(dfcode->recursive_references);
+}
+
+gboolean
+dfilter_is_recursive(dfilter_t *dfcode)
+{
+	if (!dfcode)
+		return FALSE;
+	return g_hash_table_size(dfcode->recursive_filter_sets) > 0;
+}
